steps.text:
//--- VIOC little_bird: "Insercion en Little Bird" (jugadores e IA): un MH-6 lleva VIOC_SO_LB_SIZE (4) de fuerzas
//--- especiales en los bancos (puestos de tirador, no "Cargo"), aterriza, bajan y se va (VIOC_fnc_soDoHeli). Lo tienen los
//--- paquetes con "heli" de las naciones con Little Bird (EE. UU. y Colombia, que usa el de EE. UU.; Rusia: Ka-60).
//--- La IA tambien lo usa en sus operaciones (peso VIOC_SO_LB_W), con el mismo precio y 4 soldados.
VIOC_SO_LB_W = 0.7;
VIOC_SO_LB_SIZE = 4;
VIOC_SO_LB_CLS = createHashMapFromArray [
	["US", ["RHS_MELB_MH6M", "CUP_B_MH6M_USA", "CUP_B_MH6J_USA", "B_Heli_Light_01_F"]],
	["COL", ["RHS_MELB_MH6M", "CUP_B_MH6M_USA", "AOA_littlebird_M", "B_Heli_Light_01_F"]],
	["RU", ["rhs_ka60_grey", "CUP_O_Ka60_Grey_RU", "O_Heli_Light_02_unarmed_F"]],	//--- Rusia no tiene MH-6: Ka-60 Kasatka, su helicoptero ligero
	["VANW", ["B_Heli_Light_01_F"]]
];
VIOC_SO_TYPENAMES set ["lb", "Insercion en Little Bird"];
{
	private _c = ((VIOC_SO_LB_CLS getOrDefault [_x get "nation", []]) select {
		isClass (configFile >> "CfgVehicles" >> _x) && {getNumber (configFile >> "CfgVehicles" >> _x >> "scope") >= 1} && {_x isKindOf "Helicopter"}
	}) param [0, ""];
	_x set ["vlb", if ("heli" in (_x get "types")) then {_c} else {""}];
} forEach VIOC_SO_PACKAGES;

//--- Bandos (oeste/este) que tuvieron algun jugador humano en la partida (muerto o reapareciendo sigue contando).

private _lbo = (_op get "type") == "lb";	//--- VIOC little_bird: los bancos del MH-6 son puestos de tirador (FFV), no "Cargo"
private _ffv = if (_lbo) then {(fullCrew [_veh, "turret", true]) select {isNull (_x select 0) && {(_x param [4, false]) isEqualTo true}}} else {[]};
private _free = (_veh emptyPositions "Cargo") + (count _ffv);
private _n = (_op get "size") min (_free - (count (_op getOrDefault ["pj", []])));	//--- VIOC heli_join: asiento para el jugador

steps.anchor:
if (_n < 4) exitWith {
	{deleteVehicle _x} forEach (crew _veh);
	deleteVehicle _veh;
	deleteGroup _team;
	[grpNull, [], "noseat", objNull]
};
{
	private _u = [_team, _x, _start, _pkg] call VIOC_fnc_soNewUnit;
	if (!isNull _u) then {
		_u moveInCargo _veh;
		if (vehicle _u != _veh) then {deleteVehicle _u};
	};
} forEach ([_pkg, _n] call VIOC_fnc_soPickClasses);
if (count (units _team) == 0) exitWith {
	{deleteVehicle _x} forEach (crew _veh);
	deleteVehicle _veh;
	[grpNull, [], "nounits", objNull]
};
_op set ["boarded", {vehicle _x == _veh} count (units _team)];
_team setBehaviour "CARELESS";

steps.text:
if (_n < 4) exitWith {
	{deleteVehicle _x} forEach (crew _veh);
	deleteVehicle _veh;
	deleteGroup _team;
	[grpNull, [], "noseat", objNull]
};
{
	private _u = [_team, _x, _start, _pkg] call VIOC_fnc_soNewUnit;
	if (!isNull _u) then {
		_u moveInCargo _veh;
		if (_lbo && {vehicle _u != _veh} && {count _ffv > 0}) then {_u moveInTurret [_veh, (_ffv deleteAt 0) select 3]};	//--- VIOC little_bird: a los bancos
		if (vehicle _u != _veh) then {deleteVehicle _u};
	};
} forEach ([_pkg, _n] call VIOC_fnc_soPickClasses);
if (count (units _team) == 0) exitWith {
	{deleteVehicle _x} forEach (crew _veh);
	deleteVehicle _veh;
	[grpNull, [], "nounits", objNull]
};
_op set ["boarded", {vehicle _x == _veh} count (units _team)];
_team setBehaviour "CARELESS";

case "heli": {[_op] call VIOC_fnc_soDoHeli};
case "lb": {[_op] call VIOC_fnc_soDoHeli};	//--- VIOC little_bird
default {[_op] call VIOC_fnc_soDoRaid};

case "raid": {_night && {_mode == "attack"}};
case "lb": {true};	//--- VIOC little_bird
default {false};

case "heli": {[_town, _from, _side, _mode] call VIOC_fnc_soFindLZ};
case "lb": {[_town, _from, _side, _mode] call VIOC_fnc_soFindLZ};	//--- VIOC little_bird
default {[_town, _side, selectRandom ((_o select 0) get "vunits")] call VIOC_fnc_soFindRaidStart};

if (_type == "heli") then {_air = selectRandom (_pkg get "vhelis")};
if (_type == "lb") then {_air = _pkg getOrDefault ["vlb", ""]};	//--- VIOC little_bird
[_pkg, _type, _main, _pos, _air]

_size = ((2 * round (_size / 2)) max 4) min 8;
if (_want == "lb") then {_size = VIOC_SO_LB_SIZE};	//--- VIOC little_bird: caben 4 en los bancos
if ((count _pos) < 2 || {!((_pos select 0) isEqualType 0)} || {!((_pos select 1) isEqualType 0)}) exitWith {"posicion no valida"};

if (count _pkgs == 0) exitWith {"tu bando no tiene unidades especiales en este escenario"};
if (_want == "lb" && {(_pkgs findIf {((_x select 0) getOrDefault ["vlb", ""]) != ""}) < 0}) exitWith {"tu bando no tiene Little Bird (MH-6) en este escenario"};	//--- VIOC little_bird
//--- topes: soldados pedidos vivos del bando y presupuesto de IA

publicVariable "VIOC_SO_PREQ_AVAIL";
VIOC_SO_LB_AVAIL = [west, east] apply {	//--- VIOC little_bird: nombre del Little Bird del bando ("" = no tiene)
	private _s = _x;
	private _ps = ([_s] call VIOC_fnc_soSidePackages) select {((_x select 0) getOrDefault ["vlb", ""]) != ""};
	if ((VIOC_SO_PREQ_MODE > 0) && {count _ps > 0}) then {getText (configFile >> "CfgVehicles" >> (((_ps select 0) select 0) get "vlb") >> "displayName")} else {""}
};
publicVariable "VIOC_SO_LB_AVAIL";
format ["pedidos de jugadores: modo %1 (precio x%2, enfriamiento %3 min), oeste/este con paquetes %4", VIOC_SO_PREQ_MODE, VIOC_SO_PREQ_MULT, VIOC_SO_PREQ_COOLDOWN / 60, VIOC_SO_PREQ_AVAIL] call VIOC_fnc_soLog;

	_i >= 0 && {((missionNamespace getVariable ["VIOC_SO_PREQ_AVAIL", []]) param [_i, false]) isEqualTo true}
};

//--- VIOC little_bird: tu bando tiene Little Bird (lo publica el servidor).
VIOC_SOR_fnc_lbOk = {
	private _i = [west, east] find CTI_P_SideJoined;
	private _n = if (_i >= 0) then {(missionNamespace getVariable ["VIOC_SO_LB_AVAIL", []]) param [_i, ""]} else {""};
	(_n isEqualType "") && {_n != ""}
};

private _n = VIOC_SOR_SIZES select _si;
if (_type == "lb") then {_n = 4};	//--- VIOC little_bird: 4 en los bancos
([VIOC_SOR_POS] call VIOC_SOR_fnc_target) params ["", "_what", "_prob"];

if (_type == "raid") then {_l pushBack "<t color='#aaaaaa'>A pie: salen de un pueblo tuyo a menos de 2,5 km del objetivo.</t>"};
if (_type == "lb") then {_l pushBack (if (call VIOC_SOR_fnc_lbOk) then {format ["<t color='#aaaaaa'>Little Bird (%1): siempre 4 de fuerzas especiales; aterriza, bajan y se va.</t>", [(missionNamespace getVariable ["VIOC_SO_LB_AVAIL", []]) param [[west, east] find CTI_P_SideJoined, ""]] call VIOC_SOR_fnc_esc]} else {"<t color='#F56363'>Tu bando no tiene Little Bird en este escenario.</t>"})};	//--- VIOC little_bird
_info ctrlSetStructuredText parseText format ["<t size='0.85'>%1</t>", _l joinString "<br/>"];

private _n = VIOC_SOR_SIZES select _si;
if (_type == "lb") then {_n = 4};	//--- VIOC little_bird
if (_type == "lb" && {!(call VIOC_SOR_fnc_lbOk)}) exitWith {hint "Tu bando no tiene Little Bird en este escenario: elige otro tipo."};
private _seen = [_type, _n] call VIOC_SOR_fnc_price;
